def test_allow_unicode_default_is_exactly_false():
    params = slugify_params(parse_args([None]))
    assert params['allow_unicode'] is False

def test_slugify_params_allow_unicode_flag_is_passed_through():
    params = slugify_params(parse_args([None, '--allow-unicode', 'Cool Text']))
    assert params['allow_unicode'] is True

def test_main_exit_code_on_keyboard_interrupt_is_minus_one(monkeypatch):
    class InterruptingStdout:
        def write(self, text):
            raise KeyboardInterrupt

        def flush(self):
            pass

    monkeypatch.setattr(sys, 'stdout', InterruptingStdout())
    with pytest.raises(SystemExit) as err:
        main(['prog', 'Cool Text'])
    assert err.value.code == -1

def test_main_exit_code_on_keyboard_interrupt_is_not_none(monkeypatch):
    class InterruptingStdout:
        def write(self, text):
            raise KeyboardInterrupt

        def flush(self):
            pass

    monkeypatch.setattr(sys, 'stdout', InterruptingStdout())
    with pytest.raises(SystemExit) as err:
        main(['prog', 'Cool Text'])
    assert err.value.code is not None
    assert err.value.code == -1

def test_main_exit_code_on_keyboard_interrupt_is_negative(monkeypatch):
    class InterruptingStdout:
        def write(self, text):
            raise KeyboardInterrupt

        def flush(self):
            pass

    monkeypatch.setattr(sys, 'stdout', InterruptingStdout())
    with pytest.raises(SystemExit) as err:
        main(['prog', 'Cool Text'])
    assert isinstance(err.value.code, int)
    assert err.value.code < 0
    assert err.value.code == -1

